fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    // Spec:
    // - The output vector has the same length as the input vector `a`.
    // - For each input string s, the corresponding output is a non-empty Vec<String>
    //   representing lines split on '\n', '\r', or "\r\n".
    // - Each line slice preserves line endings if keepends is true, otherwise not.
    // - Joining all output lines for a string equals the original string.
    // - No line contains internal '\r' or '\n' characters (line endings are only at the end).
    // - If the input string is empty, the output is a one-element Vec with an empty string.

    a.into_iter()
        .map(|s| {
            // Invariant:
            // - 0 <= start <= i+1 <= len
            // - lines contains collected split lines from s[0..start) segments
            // - At loop end, lines concatenated equals s[0..start]

            let mut lines = Vec::new();
            let mut start = 0;
            let bytes = s.as_bytes();
            let len = s.len();

            // Decreases clause: len - i, since i advances
            for (i, &b) in bytes.iter().enumerate() {
                if b == b'\n' {
                    // Include '\n' if keepends is true,
                    // otherwise exclude it.
                    let end = if keepends { i + 1 } else { i };
                    if start < end {
                        lines.push(s[start..end].to_string());
                    } else {
                        // Empty line (consecutive line endings)
                        lines.push(String::new());
                    }
                    start = i + 1;
                } else if b == b'\r' {
                    // Handle possible CRLF
                    if i + 1 < len && bytes[i + 1] == b'\n' {
                        let end = if keepends { i + 2 } else { i };
                        if start < end {
                            lines.push(s[start..end].to_string());
                        } else {
                            lines.push(String::new());
                        }
                        start = i + 2;
                    } else {
                        // Lone CR line ending
                        let end = if keepends { i + 1 } else { i };
                        if start < end {
                            lines.push(s[start..end].to_string());
                        } else {
                            lines.push(String::new());
                        }
                        start = i + 1;
                    }
                }
            }
            // Add remaining segment after last line ending (or whole string if none)
            if start < len {
                lines.push(s[start..].to_string());
            } else if lines.is_empty() {
                // String is empty or ends exactly on line endings, ensure at least one element
                lines.push(String::new());
            }

            // Guarantee nonempty lines vector
            if lines.is_empty() {
                lines.push(String::new());
            }

            // Ensures:
            // 1) lines.len() >= 1
            // 2) s == lines.join("")
            // 3) For each line in lines, it contains no '\n' or '\r' except possibly at end if keepends
            // 4) No line is empty unless it corresponds to empty line (e.g., consecutive line endings)
            lines
        })
        .collect()
}